type Result<T> = { ok: true; value: T } | { ok: false; error: 'invalid_json' | 'schema_mismatch' };
export function parseConfig(raw: string): Result<{port: number}> {
let value: unknown;
try { value = JSON.parse(raw) } catch { return { ok: false, error: 'invalid_json' } }
if (typeof value !== 'object' || value === null || !('port' in value) || typeof value.port !== 'number' || !Number.isInteger(value.port) || value.port < 1 || value.port > 65535) return { ok: false, error: 'schema_mismatch' };
return { ok: true, value: {port: value.port} };
}
